mapper.select:
SELECT a.profitsharing_rate AS profitsharing_rate, ps.total_fee AS total_fee FROM orders_normal_orders a INNER JOIN order_profit_sharing ps ON a.company_id = ps.company_id AND a.order_id = ps.order_id
AND ps.status = 1
AND ps.distributor_id = #{distributorId}

SELECT IFNULL(SUM(d.total_fee), 0)
FROM order_profit_sharing p
INNER JOIN order_profit_sharing_details d
	ON p.company_id = d.company_id AND p.order_profit_sharing_id = d.sharing_id
WHERE p.company_id = #{companyId}
AND p.pay_type = 'hfpay'
AND d.distributor_id = #{distributorId}
AND p.status = 1
AND p.hf_order_date >= #{hfOrderDateYmd}

SELECT IFNULL(SUM(d.total_fee), 0)
FROM order_profit_sharing p
INNER JOIN order_profit_sharing_details d
	ON p.company_id = d.company_id AND p.order_profit_sharing_id = d.sharing_id
WHERE p.company_id = #{companyId}
AND p.pay_type = 'hfpay'
AND d.distributor_id = #{distributorId}
AND p.status = 1
AND p.hf_order_date <= #{hfOrderDateYmd}

